import { BottomNav, OverlayScope, toast } from "march/ui"
import { home, compass, message, user, image, film, radio } from "march/icons"

// bir sosyal uygulamanın alt çubuğu: okunmamış sohbet sayısı, profilde yeni şey noktası, ortada Oluştur menüsü
// (uzun basış doğrudan gönderi açar); menü telefon çerçevesinin içinde açılır (OverlayScope)
export function SocialTabs() {
  let $tab = "home"
  let $unread = 4
  let $news = true
  const titles: Record<string, string> = { home: "Akış", explore: "Keşfet", chat: "Sohbet", me: "Profil" }
  const open = (id: string) => { $tab = id; if (id === "chat") $unread = 0; if (id === "me") $news = false }
  return <OverlayScope sx={{ flex: ["col", "between"], p: 2, gap: 3 }}>
    <h3 sx={{ text: ["lg", "center"] }}>{titles[$tab]}</h3>
    <BottomNav value={$tab} onChange={open} onCreate={() => toast("Yeni gönderi")} createTitle="Oluştur"
      createActions={[
        { id: "post", label: "Gönderi", icon: image, run: () => toast("Gönderi taslağı açıldı") },
        { id: "story", label: "Hikâye", icon: film, desc: "24 saat görünür" },
        { id: "live", label: "Canlı yayın", icon: radio, desc: "Takipçilerine bildirim gider" },
      ]}
      onAction={(id) => { if (id !== "post") toast(`${id === "story" ? "Hikâye" : "Canlı yayın"} başlıyor`) }}
      items={[
        { id: "home", label: "Akış", icon: home },
        { id: "explore", label: "Keşfet", icon: compass },
        { id: "chat", label: "Sohbet", icon: message, badge: () => $unread },
        { id: "me", label: "Profil", icon: user, dot: () => $news },
      ]} />
  </OverlayScope>
}

import { BottomNav, OverlayScope, Button, Badge } from "march/ui"
import { home, compass, calendar, bell, user, sparkles, image, film, radio, barChart } from "march/icons"

// BottomNav'ın bütün özellikleri: sekmeler (etkin ikon, sayı rozeti, nokta, renk, bağlantı), değer ve onChange, Oluştur
// düğmesi (onCreate, kendi ikonu, adı, halka renkleri), Oluştur menüsü (görünüm, başlık, tutamak, onAction), baloncuk,
// hareket, etiketler, görünüm, renk tonu, erişilebilir ad ve sınıf; üstteki düğmeler canlı olanları değiştirir
const LOOKS = ["fan", "stack", "sheet"] as const

export function BottomNavLab() {
  let $tab = "home"
  let $alerts = 120
  let $look = 0
  let $flat = false
  let $quiet = false
  let $log = "-"
  return <OverlayScope sx={{ flex: "col", gap: 3, p: 2 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button size="sm" variant="ghost" on:click={() => $look = ($look + 1) % LOOKS.length}>{`Menü: ${LOOKS[$look]}`}</Button>
      <Button size="sm" variant="ghost" on:click={() => $flat = !$flat}>{$flat ? "Yüzen" : "Düz"}</Button>
      <Button size="sm" variant="ghost" on:click={() => $quiet = !$quiet}>{$quiet ? "Sesli" : "Sade"}</Button>
      <Badge tone="primary">{`Sekme: ${$tab}`}</Badge>
      <span sx={{ text: "xs", color: "muted" }}>{$log}</span>
    </div>
    <BottomNav class="lab-bnav" label="Laboratuvar sekmeleri" value={() => $tab} onChange={(id) => { $tab = id; if (id === "alerts") $alerts = 0 }}
      onCreate={() => $log = "onCreate (uzun basış)"} createLabel="Yeni ekle" createIcon={sparkles} ring={["brand-pink", "brand-gold", "#22c55e"]}
      createActions={[
        { id: "post", label: "Gönderi", icon: image, desc: "Fotoğraf ya da yazı", color: "brand-orange" },
        { id: "story", label: "Hikâye", icon: film, badge: "yeni" },
        { id: "live", label: "Canlı", icon: radio, disabled: true },
        { id: "poll", label: "Anket", icon: barChart, run: () => $log = "anketin kendi run'ı" },
      ]}
      createMenu={() => LOOKS[$look]} createTitle="Ne paylaşalım?" createHandle={false} onAction={(id) => $log = `onAction: ${id}`}
      bubble={() => !$quiet} motion={() => !$quiet} labels={() => !$quiet} variant={() => ($flat ? "flat" : "floating")} tint={() => ($quiet ? "accent" : "brand")}
      items={[
        { id: "home", label: "Akış", icon: home, color: "brand-blue" },
        { id: "explore", label: "Keşfet", icon: compass, activeIcon: sparkles },
        { id: "events", label: "Takvim", icon: calendar, href: "#takvim" },
        { id: "alerts", label: "Bildirimler", icon: bell, badge: () => $alerts },
        { id: "me", label: "Profil", icon: user, dot: true, color: "brand-purple" },
      ]} />
  </OverlayScope>
}

import { test, expect, renderTest } from "march/testing"
import { BottomNavLab } from "./BottomNavLab.tsx"

// BottomNavLab'in testleri: kaydedince Testler sekmesinde çalışır
test("bir sekmeye basınca onChange değeri değiştirir ve sekme etkin olur", async () => {
  const s = renderTest(() => <BottomNavLab />)
  await s.click("Keşfet")
  expect(s.sees("Sekme: explore")).toBe(true)
})

test("120 bildirim 99+ yazılır; sekmesi açılınca sıfırlanır", async () => {
  const s = renderTest(() => <BottomNavLab />)
  expect(s.sees("99+")).toBe(true)
  await s.click("Bildirimler")
  expect(s.sees("99+")).toBe(false)
})

test("Oluştur düğmesinin adı createLabel'dan gelir; alt sayfa menüsünde başlığı görünür", async () => {
  const s = renderTest(() => <BottomNavLab />)
  await s.click("Menü: fan")
  await s.click("Menü: stack")
  expect(s.sees("Menü: sheet")).toBe(true)
  await s.click("Yeni ekle")
  expect(s.sees("Ne paylaşalım?")).toBe(true)
})

test("bir eylem seçilince onAction çalışır", async () => {
  const s = renderTest(() => <BottomNavLab />)
  await s.click("Yeni ekle")
  await s.click("Hikâye")
  await s.wait(() => s.sees("onAction: story"))
  expect(s.sees("onAction: story")).toBe(true)
})
